typedef unsigned int u_int;

struct nglMaterial {};

extern char nglWaveTransAddr[];
extern char nglBaseAddr[];
extern float TransHighlightAlphaScale;
extern float TransHighlightAlphaMin;
extern float detransparifactor;

__asm__(".equ _$nglWaveTransAddr, 0x003E3A38");
__asm__(".equ _$nglBaseAddr, 0x003E16A8");
__asm__(".equ TransHighlightAlphaScale, 0x0041E694");
__asm__(".equ TransHighlightAlphaMin, 0x0041E69C");
__asm__(".equ detransparifactor, 0x0041E6D8");

extern char nglWaveTransAddr[] asm("_$nglWaveTransAddr");
extern char nglBaseAddr[] asm("_$nglBaseAddr");

#define SCE_VIF1_S_32 0x00
#define SCE_VIF1_V3_32 0x08
#define SCE_VIF1_USN ( 1 << 14 )
#define SCE_VIF1_SET_UNPACK(addr, num, vnvl, flg) ((u_int)(0x60 | ((flg) << 7) | (vnvl)) << 24 | ((num) & 0xff) << 16 | ((addr) & 0x3ff))
#define NGL_PROG_ADDR( x, base ) ( ( (u_int)x - (u_int)base ) / 8 )

inline void nglVif1AddCommandListProgram( u_int*& Packet, u_int& DataPtr, char* Addr )
{
  Packet[0] = SCE_VIF1_SET_UNPACK( DataPtr++, 1, SCE_VIF1_S_32, 0 );
  Packet[1] = NGL_PROG_ADDR( Addr, nglBaseAddr );
  Packet += 2;
}

inline void nglVif1AddCommandListData( u_int*& Packet, u_int& DataPtr, int Mode, int QWC, void* Data, int DataSize )
{
  u_int* DataWords = (u_int*)Data;
  *(Packet++) = SCE_VIF1_SET_UNPACK( DataPtr, QWC, Mode, 0 ) | SCE_VIF1_USN;
  do {
    *(Packet++) = *(DataWords++);
    DataSize -= 4;
  } while ( DataSize );
  DataPtr += QWC;
}

void nglVif1AddWaveTransparency(u_int*& _Packet, u_int& _CmdListDataPtr, nglMaterial* Material, u_int MaterialFlags, bool standalone )
{
	u_int* Packet = _Packet;
	u_int CmdListDataPtr = _CmdListDataPtr;

	nglVif1AddCommandListProgram(  Packet, CmdListDataPtr, nglWaveTransAddr );
	float ScaleOffset[] = {TransHighlightAlphaScale, TransHighlightAlphaMin, detransparifactor};
	nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V3_32, 1, (void *) ScaleOffset, sizeof(ScaleOffset) );

	_Packet = Packet;
	_CmdListDataPtr = CmdListDataPtr;
}
